UPDATE goods_relationships SET framing = '{"slug":"paul-ramsay-foundation","tone":"rigorous, system-thinking, evidence-first","framing_notes":"Stage upgraded from cold 2026-04-24: Xero shows 2 paid invoices (small, $7,469 total) and William Frazer is tagged partner+justicehub in GHL — relationship is warmer than cold. Last comm 80 days ago (hello@ address, early Feb). PRF thinks deeply about systems change. Lead with the cost evidence, then the verified-intervention engine (ALMA), then the platform stack as the system-change lever. PRF will be skeptical of ''two people built it with hands'' — for them, lead with infrastructure, not artisanship.","claims_to_lead_with":["contained:claim-cost-comparison","contained:claim-room-3-community-already-doing-it","contained:claim-platform-stack"],"claims_to_avoid":["contained:claim-built-by-hand"],"primary_contact":"William Frazer (Jonas + Prebhjot + Julia CC)","last_communicated_at":null,"synced_at":"2026-06-10T00:40:49.288Z"}'::jsonb, updated_at = now() WHERE id = '54916f2e-d940-4788-a9fb-bfc0f565faa7';
UPDATE goods_relationships SET framing = '{"slug":"minderoo","tone":"communities-first, evidence-rich, place-based, structurally honest, board-defensible","framing_notes":"Minderoo''s current public strategy is Communities-first: place-based engagement, local knowledge and lived experience, stronger child and family supports, and vibrant connected communities. Lead with the anchor-community hold, not JusticeHub as a product. JusticeHub is the evidence layer under the community work; The Brave Ones is the human trace layer; the library is the destination, not the opening noun. Use Minderoo''s own role language where possible: Partner, Develop, Generate Evidence, Advocate. Primary ask: $2.9M over 3 years (the canonical Three Circles ask). Best staged entry: $780K for Year 1 with a pathway into Years 2-3. Use the older $3.43M Crescendo frame only if Lucy invites ACT upward into the expanded library / artefact expression. Avoid the confrontational frame — they fund builders, not critics. Source docs: three-circles.md (canonical pitch), how-should-act-pitch-minderoo-in-line-with-its-current-strategy-and-what-money-f.md (strategy synthesis), and the-full-idea.md (comprehensive walkthrough).","claims_to_lead_with":["justicehub:claim-ten-anchor-communities-filter-is-relationship","justicehub:claim-three-circles-start-at-the-edge","justicehub:claim-fire-crescendo-build-slowly","justicehub:claim-tier-pricing-against-detention-cost","justicehub:claim-the-library-is-the-destination","justicehub:claim-authority-at-the-edge-lineage","justicehub:claim-the-brave-ones-counter-mugshot"],"claims_to_avoid":["contained:claim-evidence-is-settled-question-is-political-will"],"primary_contact":"Lucy Stronach","last_communicated_at":"2026-05-14","synced_at":"2026-06-10T00:40:49.288Z"}'::jsonb, updated_at = now() WHERE id = '33a5d348-a3c3-4c1b-8a8d-05b9d2602421';
